/**
 * Sample library for the design preview: species, facts and photos, no recordings yet.
 * The list lives in birds.json so the photo script can read it.
 * The real library (with audio, recordist and license) will come from ../../../birds.json,
 * generated by the audio pipeline.
 */
import { getLocales } from 'expo-localization';

import birdList from './birds.json';
import { PHOTO_FILES } from './photo-files';
import photoCredits from './photos.json';

export interface LibraryBird {
  id: string;
  commonName: string;
  scientificName: string;
  regions: string[];
  fact: string;
  /** Common name of the bird's family, e.g. "Thrushes". */
  family?: string;
  /** Size compared with a sparrow, robin or crow. */
  size?: string;
  /** Where to look for it. */
  habitat?: string;
  /** What its song sounds like. */
  listen?: string;
}

export interface PhotoCredit {
  artist: string;
  license: string;
  source: string;
  file: string;
  /** Where the bird sits across the photo, 0 = left edge, 1 = right edge. Used to aim tall crops. */
  focusX?: number;
}

export const BIRDS: LibraryBird[] = birdList;
const credits: Record<string, PhotoCredit> = photoCredits;

/** The bird's photo (for <Image source>) and its credit, if one was downloaded. */
export function photoFor(id: string): { source: number; credit: PhotoCredit } | undefined {
  const source = PHOTO_FILES[id];
  const credit = credits[id];
  return source && credit ? { source, credit } : undefined;
}

/** Every photo credit, in library order, for the Credits screen. */
export const PHOTO_CREDITS = BIRDS.filter((b) => PHOTO_FILES[b.id] && credits[b.id]).map((b) => ({
  bird: b.commonName,
  ...credits[b.id]!,
}));

export const REGION_NAMES: Record<string, string> = {
  'north-america': 'North America',
  europe: 'Europe',
};

const NORTH_AMERICA = ['US', 'CA', 'MX'];
const EUROPE = ['GB', 'IE', 'FR', 'DE', 'ES', 'PT', 'IT', 'NL', 'BE', 'LU', 'CH', 'AT', 'DK', 'SE', 'NO', 'FI', 'IS',
  'PL', 'CZ', 'SK', 'HU', 'SI', 'HR', 'RO', 'BG', 'GR', 'EE', 'LV', 'LT', 'UA'];

function regionForCountry(country: string | null | undefined): string | undefined {
  if (!country) return undefined;
  const c = country.toUpperCase();
  if (NORTH_AMERICA.includes(c)) return 'north-america';
  if (EUROPE.includes(c)) return 'europe';
  return undefined;
}

/** Region from the device's language/region setting. No location permission involved. */
export function detectRegion(): string | undefined {
  try {
    for (const locale of getLocales()) {
      const region = regionForCountry(locale.regionCode);
      if (region) return region;
    }
  } catch {}
  try {
    const locale = Intl.DateTimeFormat().resolvedOptions().locale;
    return regionForCountry(locale.split(/[-_]/).find((p) => /^[A-Za-z]{2}$/.test(p) && p === p.toUpperCase()));
  } catch {}
  return undefined;
}

export function birdsFor(region: string | undefined, worldwide: boolean): LibraryBird[] {
  if (worldwide || !region) return BIRDS;
  const local = BIRDS.filter((b) => b.regions.includes(region));
  return local.length ? local : BIRDS;
}

export const birdById = (id: string | undefined) => BIRDS.find((b) => b.id === id);
